package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// Spec 181, end to end: trilha hooks turns the hook on, and a real git commit
// with a source file over 500 lines is stopped with the way to split it,
// while files within the limits, lockfiles and generated files go through.
func TestPrecommitHookStopsTheCommit(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not installed")
	}
	if runtime.GOOS == "windows" {
		t.Skip("the hook is a POSIX script; the check itself is covered by internal/precommit")
	}
	repo, _ := filepath.Abs(filepath.Join("..", ".."))
	tmp := t.TempDir()
	bin := filepath.Join(tmp, "bin")
	os.MkdirAll(bin, 0o755)
	run(t, repo, "go", "build", "-o", filepath.Join(bin, "trilha"), "./cmd/trilha")

	proj := filepath.Join(tmp, "loja")
	os.MkdirAll(filepath.Join(proj, "app"), 0o755)
	write := func(p, body string) {
		t.Helper()
		full := filepath.Join(proj, filepath.FromSlash(p))
		os.MkdirAll(filepath.Dir(full), 0o755)
		if err := os.WriteFile(full, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("go.mod", "module example.com/loja\n\ngo 1.22\n")
	env := append(os.Environ(), "PATH="+bin+string(os.PathListSeparator)+os.Getenv("PATH"), "TRILHA_LANG=en",
		"GIT_AUTHOR_NAME=t", "GIT_AUTHOR_EMAIL=t@example.com", "GIT_COMMITTER_NAME=t", "GIT_COMMITTER_EMAIL=t@example.com")
	sh := func(args ...string) (string, error) {
		cmd := exec.Command(args[0], args[1:]...)
		cmd.Dir, cmd.Env = proj, env
		out, err := cmd.CombinedOutput()
		return string(out), err
	}
	must := func(args ...string) string {
		t.Helper()
		out, err := sh(args...)
		if err != nil {
			t.Fatalf("%v: %v\n%s", args, err, out)
		}
		return out
	}
	must("git", "init", "-q")
	if out := must(filepath.Join(bin, "trilha"), "hooks"); !strings.Contains(out, ".githooks/pre-commit") || !strings.Contains(out, "core.hooksPath") {
		t.Fatalf("trilha hooks = %s", out)
	}

	write("app/page.go", "package app\n"+strings.Repeat("var _ = 1\n", 600))
	must("git", "add", "-A")
	out, err := sh("git", "commit", "-qm", "grande")
	if err == nil {
		t.Fatal("the commit of a 601-line page.go went through")
	}
	for _, want := range []string{"app/page.go", "601 lines (limit 500)", "Split each file now", "same package"} {
		if !strings.Contains(out, want) {
			t.Errorf("the message lacks %q:\n%s", want, out)
		}
	}

	write("app/page.go", "package app\n")
	write("go.sum", strings.Repeat("example.com/x v1.0.0 h1:abc=\n", 4000))
	write("trilha_gen.go", "// Code generated by trilha gen. DO NOT EDIT.\n\npackage main\n"+strings.Repeat("var _ = 1\n", 3000))
	must("git", "add", "-A")
	if out, err := sh("git", "commit", "-qm", "dentro"); err != nil {
		t.Fatalf("a commit within the limits was stopped: %v\n%s", err, out)
	}
}
